def wiggleSort(nums):
    # Step 1: Find the median (kᵗʰ largest, k = ⌊n/2⌋)
    def find_median(nums):
        def select(k):
            left, right = 0, len(nums) - 1
            while left <= right:
                pivot = nums[right]
                store = left
                for i in range(left, right):
                    if nums[i] < pivot:
                        nums[store], nums[i] = nums[i], nums[store]
                        store += 1
                nums[store], nums[right] = nums[right], nums[store]
                if store == k:
                    return nums[store]
                elif store < k:
                    left = store + 1
                else:
                    right = store - 1
        n = len(nums)
        return select((n - 1) // 2)

    n = len(nums)
    median = find_median(nums[:])  # work on a copy to avoid changing nums early

    # Virtual indexing
    def mapped_index(i):
        return (1 + 2 * i) % (n | 1)

    left, i, right = 0, 0, n - 1
    # 3-way partition around the median, using virtual indexing
    while i <= right:
        mi = mapped_index(i)
        ml = mapped_index(left)
        mr = mapped_index(right)
        if nums[mi] > median:
            nums[ml], nums[mi] = nums[mi], nums[ml]
            left += 1
            i += 1
        elif nums[mi] < median:
            nums[mr], nums[mi] = nums[mi], nums[mr]
            right -= 1
        else:
            i += 1
